<?php

namespace App\Http\Controllers;

use App\Models\AuditLog;
use App\Models\Service;
use Illuminate\Http\Request;
use Illuminate\Support\Arr;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\Rule;

class AdminServiceController extends Controller
{
    public function index(){ $this->admin(); return view('admin.services.index',['services'=>Service::withCount('orders')->orderBy('sort_order')->get()]); }
    public function create(){ $this->admin(); return view('admin.services.form',['service'=>new Service]); }
    public function edit(Service $service){ $this->admin(); return view('admin.services.form',['service'=>$service->load(['variants','priceTiers','addons'])]); }
    public function store(Request $request){ $this->admin(); $data=$this->validated($request); $service=DB::transaction(function()use($request,$data){$service=Service::create($this->serviceData($data));$service->update($this->capabilities($request));$this->syncChildren($service,$request);$this->audit($request,$service,'service_created',[], $service->toArray());return $service;});return redirect()->route('admin.services.edit',$service)->with('ok','Servicio creado.'); }
    public function update(Request $request,Service $service){$this->admin();$data=$this->validated($request,$service);$old=$service->toArray();DB::transaction(function()use($request,$data,$service,$old){$service->update($this->serviceData($data));$service->update($this->capabilities($request));$this->syncChildren($service,$request);$this->audit($request,$service,'service_updated',$old,$service->fresh()->toArray());});return back()->with('ok','Servicio actualizado.');}
    public function duplicate(Request $request,Service $service){$this->admin();$copy=DB::transaction(function()use($request,$service){$service->load(['variants','priceTiers','addons']);$copy=$service->replicate();$copy->name.=' (copia)';$copy->slug=Str::slug($copy->name).'-'.Str::lower(Str::random(5));$copy->active=false;$copy->save();foreach(['variants','priceTiers','addons'] as $relation)foreach($service->$relation as $child)$copy->$relation()->save($child->replicate());$this->audit($request,$copy,'service_duplicated',[], $copy->toArray());return $copy;});return redirect()->route('admin.services.edit',$copy)->with('ok','Servicio duplicado como inactivo.');}
    public function toggle(Request $request,Service $service){$this->admin();$old=$service->active;$service->update(['active'=>!$old]);$this->audit($request,$service,$service->active?'service_activated':'service_deactivated',['active'=>$old],['active'=>$service->active]);return back()->with('ok','Estado actualizado.');}
    public function destroy(Request $request,Service $service){$this->admin();if($service->orders()->exists()){$service->update(['active'=>false]);$this->audit($request,$service,'service_deactivated_with_orders',['active'=>true],['active'=>false]);return back()->with('ok','El servicio tiene pedidos y fue desactivado; no se eliminó.');}$this->audit($request,$service,'service_deleted',$service->toArray(),[]);$service->delete();return back()->with('ok','Servicio eliminado.');}
    public function reorder(Request $request){$this->admin();$data=$request->validate(['orders'=>'required|array','orders.*'=>'integer|min:0']);foreach($data['orders'] as $id=>$order)Service::whereKey($id)->update(['sort_order'=>$order]);return back()->with('ok','Orden actualizado.');}

    private function validated(Request $request,?Service $service=null):array{return $request->validate(['name'=>'required|string|max:120','slug'=>['required','alpha_dash','max:140',Rule::unique('services','slug')->ignore($service)],'short_description'=>'nullable|string|max:180','description'=>'required|string|max:3000','icon'=>'nullable|string|max:40','instructions'=>'nullable|string|max:3000','pricing_model'=>'required|in:per_page,per_unit,fixed,tiered,manual','price_per_page'=>'nullable|numeric|min:0','billing_unit'=>'required|string|max:40','sort_order'=>'required|integer|min:0','requires_file'=>'nullable|boolean','requires_pages'=>'nullable|boolean','requires_quantity'=>'nullable|boolean','allows_letter'=>'nullable|boolean','allows_legal'=>'nullable|boolean','allows_duplex'=>'nullable|boolean','pickup_return'=>'nullable|boolean','allows_urgent'=>'nullable|boolean','active'=>'nullable|boolean','variants'=>'nullable|array','variants.*.name'=>'nullable|string|max:100','variants.*.group_name'=>'nullable|string|max:100','variants.*.price_effect'=>'nullable|in:surcharge,replace','variants.*.price'=>'nullable|numeric|min:0','tiers'=>'nullable|array','tiers.*.label'=>'nullable|string|max:100','tiers.*.minimum_quantity'=>'nullable|integer|min:1','tiers.*.maximum_quantity'=>'nullable|integer|min:1','tiers.*.price'=>'nullable|numeric|min:0','addons'=>'nullable|array','addons.*.name'=>'nullable|string|max:100','addons.*.description'=>'nullable|string|max:300','addons.*.price_type'=>'nullable|in:fixed,per_unit','addons.*.price'=>'nullable|numeric|min:0']);}
    private function serviceData(array $data):array{return array_merge(Arr::except($data,['variants','tiers','addons']),['calculation_type'=>$data['pricing_model']==='manual'?'quote':'automatic','requires_file'=>request()->boolean('requires_file'),'requires_pages'=>request()->boolean('requires_pages'),'requires_quantity'=>request()->boolean('requires_quantity'),'allows_letter'=>request()->boolean('allows_letter'),'allows_legal'=>request()->boolean('allows_legal'),'allows_duplex'=>request()->boolean('allows_duplex'),'pickup_return'=>request()->boolean('pickup_return'),'allows_urgent'=>request()->boolean('allows_urgent'),'active'=>request()->boolean('active')]);}
    private function syncChildren(Service $service,Request $request):void{$service->variants()->delete();foreach($request->input('variants',[]) as $i=>$row)if(!empty($row['name']))$service->variants()->create($row+['active'=>true,'sort_order'=>$i]);$service->priceTiers()->delete();foreach($request->input('tiers',[]) as $i=>$row)if(!empty($row['label'])&&isset($row['minimum_quantity'],$row['price']))$service->priceTiers()->create($row+['active'=>true,'sort_order'=>$i]);$service->addons()->delete();foreach($request->input('addons',[]) as $i=>$row)if(!empty($row['name'])&&isset($row['price']))$service->addons()->create($row+['active'=>true,'sort_order'=>$i]);}
    private function audit(Request $request,Service $service,string $action,array $old,array $new):void{AuditLog::create(['user_id'=>Auth::id(),'action'=>$action,'auditable_type'=>Service::class,'auditable_id'=>$service->id,'old_values'=>$old,'new_values'=>$new,'ip_address'=>$request->ip()]);}
    private function capabilities(Request $request):array{return collect(['requires_copies','requires_topic','requires_education_level','allows_cover','allows_images','allows_stapling','requires_output_format','requires_pickup_instructions','requires_deposit'])->mapWithKeys(fn($field)=>[$field=>$request->boolean($field)])->all();}
    private function admin():void{abort_unless(Auth::user()?->is_admin,403);}
}
